const base=$('Setup Complete').first().json;
const plan=$('Plan Oak Properties').first().json;
let res=null;
try{res=$('Create Oak Properties').first().json;}catch(e){res=null;}
const warnings=[];
if(plan.lookup_error)warnings.push('Could not read the HubSpot contact schema: '+plan.lookup_error+'. Check the HubSpot credential and its crm.schemas.contacts scopes.');
const created=(res&&Array.isArray(res.results))?res.results.map(r=>r.name):[];
if(res&&res.error)warnings.push('Creating the oak_* contact properties failed: '+String(res.error)+'. The HubSpot credential needs the crm.schemas.contacts.write scope.');
else if(plan.missing_count>0&&!created.length&&res)warnings.push('HubSpot accepted the property request but returned no created properties. Verify the oak_* properties by hand.');
const propsReady=plan.missing_count===0||created.length===plan.missing_count;
const wanted=$('Plan Slack Channels').all().map(i=>i.json);
let slackItems=[];
try{slackItems=$('Create Slack Channel').all().map(i=>i.json);}catch(e){slackItems=[];}
const channels=wanted.map(function(w,idx){
  const r=slackItems[idx]||{};
  const err=r.error?String(typeof r.error==='object'?(r.error.message||JSON.stringify(r.error)):r.error):'';
  const taken=/name_taken/i.test(err);
  return{name:w.channel_name,tier:w.tier,visibility:w.visibility,id:r.id||null,state:r.id?'created':(taken?'already_exists':'failed'),error:(r.id||taken)?null:(err||'no response from Slack')};
});
const failedChannels=channels.filter(c=>c.state==='failed');
for(const c of failedChannels)warnings.push('Slack channel #'+c.name+' could not be provisioned: '+c.error+'. The Slack credential needs the channels:manage and groups:write scopes.');
const slackReady=failedChannels.length===0;
const next=['Map HubSpot owner ids to Slack user ids under slack.owner_directory in the policy if you want owner DMs.','Activate workflow 01 and point the booth scanner at its production webhook URL.'];
if(!slackReady)next.unshift('Create the remaining Slack channels by hand, or reconnect the Slack credential with channels:manage and groups:write.');
return[{json:Object.assign({},base,{hubspot_properties:{schema_read:plan.schema_read,already_present:plan.already_present,created,missing_after_setup:propsReady?[]:plan.missing_names.filter(n=>created.indexOf(n)<0),ready:propsReady},slack_channels:{requested:channels.length,created:channels.filter(c=>c.state==='created').map(c=>c.name),already_existed:channels.filter(c=>c.state==='already_exists').map(c=>c.name),failed:failedChannels.map(c=>c.name),detail:channels,ready:slackReady},crm_tagging_ready:propsReady,alerting_ready:slackReady,warnings,next})}];

let p={};
try{p=JSON.parse($('Enable Out-of-Scope Route').first().json.document_json||'{}');}catch(e){p={};}
const notif=p.notifications||{};
const privateList=((p.slack||{}).private_channels)||[];
const seen=new Set();
const rows=[];
for(const key of Object.keys(notif)){
  const cfg=notif[key];
  if(!cfg||typeof cfg!=='object'||!cfg.channel)continue;
  const name=String(cfg.channel).replace(/^#/,'').trim().toLowerCase();
  if(!name||seen.has(name))continue;
  seen.add(name);
  rows.push({json:{channel_name:name,tier:key,visibility:privateList.indexOf(name)>=0?'private':'public'}});
}
if(!rows.length)rows.push({json:{channel_name:'booth-review',tier:'fallback',visibility:'public'}});
return rows;
